package org.skhuconnect.threshold.controller;
import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import org.skhuconnect.threshold.dto.PublicThresholdSettingResponse; import org.skhuconnect.threshold.repository.ThresholdSettingRepository; import org.springframework.data.domain.Sort; import org.springframework.web.bind.annotation.*; import java.util.List;
@Tag(name="Threshold Settings",description="청원 임계치 설정 조회 API") @RestController @RequestMapping("/connect/threshold-settings") public class PublicThresholdSettingController { private final ThresholdSettingRepository repository; public PublicThresholdSettingController(ThresholdSettingRepository repository){this.repository=repository;} @Operation(summary="청원 임계치 설정 조회") @GetMapping public List<PublicThresholdSettingResponse> findAll(){return repository.findAll(Sort.by("category")).stream().map(PublicThresholdSettingResponse::from).toList();} }
